package moe.cangku.reader;

import android.app.*;
import android.content.*;
import android.text.InputType;
import android.widget.*;
import android.view.*;
import org.json.*;
import org.jsoup.nodes.Element;
import java.util.*;
import java.util.function.Consumer;

/** Adaptive native companion dialogs. Only explicit poll save buttons issue writes. */
final class AuthoringExtras {
    private AuthoringExtras(){}
    private static AlertDialog.Builder dialog(MainActivity h){return new AlertDialog.Builder(new ContextThemeWrapper(h,h.design().dark?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert));}
    private static LinearLayout form(MainActivity h){LinearLayout x=new LinearLayout(h);x.setOrientation(1);h.design().pad(x,20,12,20,12);return x;}
    private static EditText field(MainActivity h,LinearLayout box,String label,String value,boolean multi){box.addView(h.design().text(label,13,h.design().muted,true));EditText e=new EditText(h);e.setTextColor(h.design().text);e.setHintTextColor(h.design().muted);e.setText(value);e.setTextSize(15);e.setHint(label);e.setSingleLine(!multi);if(multi){e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);e.setMinLines(3);}box.addView(e,new LinearLayout.LayoutParams(-1,-2));return e;}
    private static ScrollView scroll(MainActivity h,LinearLayout box){ScrollView s=new ScrollView(h);s.setFillViewport(false);s.addView(box);return s;}
    private static String value(EditText e){return e.getText().toString();}
    private interface Action {void run()throws Exception;}
    private static void submit(AlertDialog d,MainActivity h,Action action){d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{try{action.run();}catch(Exception e){h.toast(e.getMessage());}}));d.show();}
    static void show(MainActivity h,String tool,String selected,Consumer<String> done){show(h,tool,selected,done,null);}
    static void show(MainActivity h,String tool,String selected,Consumer<String> done,Consumer<Consumer<String>> uploadImage){
        final String text=selected==null||selected.isEmpty()?"文字":selected;
        switch(tool){
            case "fontFamily":dialog(h).setTitle("字体").setItems(EditorExtraRules.FONT_NAMES,(d,n)->done.accept(EditorExtraRules.font(n,text))).show();return;
            case "lineHeight":String[] heights={"1","1.15","1.5","1.75","2","2.5","3"};dialog(h).setTitle("段落行高").setItems(heights,(d,n)->done.accept(EditorExtraRules.lineHeight(heights[n],text))).show();return;
            case "rainbow":done.accept(EditorExtraRules.inline("text-rainbow",text));return;
            case "blackbar":done.accept(EditorExtraRules.inline("text-forbidden",text));return;
            case "emoji":symbols(h,"表情",EditorExtraRules.EMOJI,done);return;
            case "special":symbols(h,"特殊字符",EditorExtraRules.SPECIAL,done);return;
            case "collapse":collapse(h,selected,done);return;
            case "randomFileName":random(h,done);return;
            case "table":table(h,selected,done);return;
            case "poll":new ReferencePicker(h,false,done,uploadImage).open();return;
            case "lottery":if(!EditorExtraRules.lotteryAllowed(h.account())){h.toast("抽奖插入仅对官网管理员和编辑开放");return;}new ReferencePicker(h,true,done,uploadImage).open();return;
            default:h.toast("暂不支持此功能");
        }
    }
    private static void symbols(MainActivity h,String title,String[] items,Consumer<String> done){LinearLayout box=form(h);GridLayout grid=new GridLayout(h);grid.setColumnCount(5);for(String item:items){TextView b=h.design().button(item,false,()->{});GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=0;p.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);p.setMargins(2,4,2,4);grid.addView(b,p);b.setContentDescription("插入 "+item);}box.addView(grid);AlertDialog d=dialog(h).setTitle(title).setView(scroll(h,box)).setNegativeButton("取消",null).create();for(int i=0;i<grid.getChildCount();i++){final String item=items[i];grid.getChildAt(i).setOnClickListener(v->{done.accept(EditorExtraRules.esc(item));d.dismiss();});}d.show();}
    private static void collapse(MainActivity h,String selected,Consumer<String> done){LinearLayout box=form(h);EditText title=field(h,box,"折叠标题","",false),content=field(h,box,"折叠内容",org.jsoup.Jsoup.parse(selected==null?"":selected).text(),true);CheckBox show=new CheckBox(h);show.setText("默认展开");show.setTextColor(h.design().text);box.addView(show);AlertDialog d=dialog(h).setTitle("插入折叠内容").setView(scroll(h,box)).setNegativeButton("取消",null).setPositiveButton("插入",null).create();submit(d,h,()->{done.accept(EditorExtraRules.collapse(value(title),value(content),show.isChecked()));d.dismiss();});}
    private static void random(MainActivity h,Consumer<String> done){LinearLayout box=form(h);EditText name=field(h,box,"随机文件名",EditorExtraRules.randomFileName(),false);name.setKeyListener(null);box.addView(h.design().button("重新生成",false,()->name.setText(EditorExtraRules.randomFileName())));box.addView(h.design().button("复制文件名",false,()->{((ClipboardManager)h.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("随机文件名",value(name)));h.toast("已复制");}));dialog(h).setTitle("随机文件名").setView(box).setNegativeButton("关闭",null).setPositiveButton("插入",(d,w)->done.accept(EditorExtraRules.esc(value(name)))).show();}
    static void editImage(MainActivity h,String original,Consumer<String> done){editImage(h,original,done,null);}
    static void editImage(MainActivity h,String original,Consumer<String> done,Consumer<Consumer<String>> uploadImage){try{Element img=EditorExtraRules.image(original);LinearLayout box=form(h);EditText src=field(h,box,"图片地址（替换图片）",img.attr("src"),false),alt=field(h,box,"图片说明",img.attr("alt"),false),width=field(h,box,"宽度（像素或百分比，留空自动）",styleValue(img.attr("style"),"width").isEmpty()?img.attr("width"):styleValue(img.attr("style"),"width"),false),height=field(h,box,"高度（像素或百分比，留空自动）",styleValue(img.attr("style"),"height").isEmpty()?img.attr("height"):styleValue(img.attr("style"),"height"),false);Element a=img.parent();EditText link=field(h,box,"图片链接（留空移除）",a!=null&&a.tagName().equals("a")?a.attr("href"):"",false);box.addView(h.design().button("打开图片链接",false,()->{try{h.startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(EditorExtraRules.web(value(link),false))));}catch(Exception e){h.toast("链接无效或没有可打开的应用");}}));if(uploadImage!=null)box.addView(h.design().button("从设备选择替换图片",false,()->uploadImage.accept(url->{if(!h.isFinishing())src.setText(url);})));CheckBox blur=new CheckBox(h);blur.setText("图片模糊化（官网 blur-img 样式）");blur.setTextColor(h.design().text);blur.setChecked(img.hasClass("blur-img"));box.addView(blur);AlertDialog d=dialog(h).setTitle("图片设置").setView(scroll(h,box)).setNegativeButton("取消",null).setNeutralButton("删除图片",(x,w)->dialog(h).setTitle("删除这张图片？").setNegativeButton("取消",null).setPositiveButton("删除",(q,n)->done.accept("")).show()).setPositiveButton("应用",null).create();submit(d,h,()->{done.accept(EditorExtraRules.updateImage(original,value(src),value(alt),value(width),value(height),blur.isChecked(),value(link)));d.dismiss();});}catch(Exception e){h.toast(e.getMessage());}}
    private static void table(MainActivity h,String selected,Consumer<String> done){
        final String original=selected==null?"":selected;Element existing=org.jsoup.Jsoup.parseBodyFragment(original).selectFirst("table");LinearLayout box=form(h);List<Element> oldRows=existing==null?Collections.emptyList():existing.select("tr");int initialRows=existing==null?2:Math.max(1,oldRows.size()),initialCols=existing==null?2:1;for(Element row:oldRows)initialCols=Math.max(initialCols,row.childrenSize());
        EditText rows=field(h,box,"行数（最多 30）",String.valueOf(initialRows),false),cols=field(h,box,"列数（最多 12）",String.valueOf(initialCols),false);LinearLayout cellsBox=form(h);box.addView(cellsBox);ArrayList<EditText> cells=new ArrayList<>();ArrayList<String> values=new ArrayList<>();int[] grid={initialRows,initialCols};for(int i=0;i<initialRows;i++)for(int j=0;j<initialCols;j++)values.add(i<oldRows.size()&&j<oldRows.get(i).childrenSize()?oldRows.get(i).child(j).text():"");
        Runnable rebuild=()->{int r=Integer.parseInt(value(rows)),c=Integer.parseInt(value(cols));if(r<1||r>30||c<1||c>12||r*c>180)throw new IllegalArgumentException("最多 30 行、12 列、180 格");ArrayList<String> prev=new ArrayList<>();for(EditText e:cells)prev.add(value(e));if(!prev.isEmpty()){values.clear();for(int i=0;i<r;i++)for(int j=0;j<c;j++)values.add(i<grid[0]&&j<grid[1]?prev.get(i*grid[1]+j):"");}cells.clear();cellsBox.removeAllViews();for(int i=0;i<r;i++)for(int j=0;j<c;j++)cells.add(field(h,cellsBox,"第 "+(i+1)+" 行 · 第 "+(j+1)+" 列",i*c+j<values.size()?values.get(i*c+j):"",false));grid[0]=r;grid[1]=c;};try{rebuild.run();}catch(Exception e){h.toast(e.getMessage());return;}
        box.addView(h.design().button("应用行列数",false,()->{try{rebuild.run();}catch(Exception e){h.toast(e.getMessage());}}));String style=existing==null?"":existing.attr("style");EditText width=field(h,box,"表格宽度（如 100% 或 600，留空自动）",styleValue(style,"width"),false),height=field(h,box,"表格高度（可空）",styleValue(style,"height"),false);Spinner border=new Spinner(h),align=new Spinner(h);String[] borders={"solid","dashed","dotted","none"},aligns={"left","center","right"};border.setAdapter(new ArrayAdapter<>(h,android.R.layout.simple_spinner_dropdown_item,new String[]{"实线边框","虚线边框","点线边框","无边框"}));align.setAdapter(new ArrayAdapter<>(h,android.R.layout.simple_spinner_dropdown_item,new String[]{"靠左","居中","靠右"}));box.addView(border);box.addView(align);for(int i=0;i<aligns.length;i++)if(styleValue(style,"text-align").equals(aligns[i]))align.setSelection(i);for(int i=0;i<borders.length;i++)if(styleValue(style,"border").contains(borders[i]))border.setSelection(i);box.addView(h.design().text("未修改的单元格保留原有文字样式和链接。合并或嵌套表格请使用源码模式。",12,h.design().muted,false));AlertDialog d=dialog(h).setTitle(existing==null?"插入表格":"编辑表格").setView(scroll(h,box)).setNegativeButton("取消",null).setPositiveButton("应用",null).create();submit(d,h,()->{if(Integer.parseInt(value(rows))!=grid[0]||Integer.parseInt(value(cols))!=grid[1])throw new IllegalArgumentException("请先点击应用行列数");ArrayList<String> result=new ArrayList<>();for(EditText e:cells)result.add(value(e));done.accept(EditorExtraRules.table(original,grid[0],grid[1],result,value(width),value(height),borders[border.getSelectedItemPosition()],aligns[align.getSelectedItemPosition()]));d.dismiss();});
    }
    private static String styleValue(String style,String key){java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?i)(?:^|;)\\s*"+key+"\\s*:\\s*([^;]+)").matcher(style);return m.find()?m.group(1).trim():"";}
    private static final class ReferencePicker {
        final MainActivity h;final boolean lottery;final Consumer<String> done;final Consumer<Consumer<String>> upload;final long uid;AlertDialog dialog;LinearLayout root,list;EditText search;TextView pageText;int page=1,totalPages=1,sequence;boolean loading;
        ReferencePicker(MainActivity host,boolean l,Consumer<String> d,Consumer<Consumer<String>> u){h=host;lottery=l;done=d;upload=u;uid=host.account()==null?0:host.account().optLong("id");}
        boolean alive(){return dialog!=null&&dialog.isShowing()&&h.account()!=null&&uid==h.account().optLong("id");}
        void open(){root=form(h);search=field(h,root,"搜索主题","",false);root.addView(h.design().button("搜索",false,()->{page=1;load();}));if(!lottery&&EditorExtraRules.permission(h.account(),"edit_polls"))root.addView(h.design().button("＋ 创建投票",false,()->pollForm(null)));list=form(h);root.addView(list);LinearLayout nav=new LinearLayout(h);nav.setGravity(Gravity.CENTER);pageText=h.design().text("",13,h.design().muted,false);nav.addView(h.design().button("上一页",false,()->{if(!loading&&page>1){page--;load();}}));nav.addView(pageText);nav.addView(h.design().button("下一页",false,()->{if(!loading&&page<totalPages){page++;load();}}));root.addView(nav);dialog=AuthoringExtras.dialog(h).setTitle(lottery?"插入抽奖":"插入我的投票").setView(scroll(h,root)).setNegativeButton("取消",null).create();dialog.show();load();}
        void load(){if(!alive())return;loading=true;int run=++sequence;list.removeAllViews();list.addView(h.design().text("正在载入…",14,h.design().muted,false));Map<String,String> p=ApiClient.params("page",String.valueOf(page),"per_page","15","include","user");if(!lottery)p.put("user_id",String.valueOf(uid));if(!value(search).trim().isEmpty())p.put("search",value(search).trim());h.task(()->h.client().get(lottery?"lottery/list":"poll/list",p),r->{if(!alive()||run!=sequence)return;loading=false;list.removeAllViews();JSONObject pagination=r.optJSONObject("meta");pagination=pagination==null?null:pagination.optJSONObject("pagination");totalPages=pagination==null?1:Math.max(1,pagination.optInt("total_pages",1));pageText.setText(page+" / "+totalPages);JSONArray rows=r.optJSONArray("data");if(rows==null||rows.length()==0)list.addView(h.design().text("暂无可插入的"+(lottery?"抽奖":"投票"),14,h.design().muted,false));if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject x=rows.optJSONObject(i);if(x==null)continue;long id=x.optLong("id");list.addView(h.design().text("#"+id+"  "+x.optString(lottery?"name":"title"),15,h.design().text,true));list.addView(h.design().text(lottery?(x.optBoolean("is_finished")?"已开奖":"未开奖"):(x.optBoolean("image_mode")?"图片":"文本")+" · "+(x.optBoolean("multi_select")?"多选":"单选"),12,h.design().muted,false));list.addView(h.design().button("插入",false,()->{if(alive()){done.accept(EditorExtraRules.reference(lottery?"lottery":"poll",id));dialog.dismiss();}}));if(!lottery&&EditorExtraRules.permission(h.account(),"edit_polls"))list.addView(h.design().button("修改投票",false,()->h.task(()->h.client().get("poll/info",ApiClient.params("id",String.valueOf(id))),r2->{if(alive())pollForm(r2.optJSONObject("data"));},h::toast)));}},e->{if(!alive()||run!=sequence)return;loading=false;list.removeAllViews();list.addView(h.design().text(e,14,h.design().muted,false));list.addView(h.design().button("重试",false,this::load));});}
        void pollForm(JSONObject data){if(!alive()||!EditorExtraRules.permission(h.account(),"edit_polls"))return;JSONObject base=data==null?new JSONObject():data;LinearLayout box=form(h);EditText title=field(h,box,"投票主题",base.optString("title"),false);CheckBox images=new CheckBox(h),multi=new CheckBox(h);images.setText("图片模式（每项需图片）");multi.setText("多选");images.setTextColor(h.design().text);multi.setTextColor(h.design().text);images.setChecked(base.optBoolean("image_mode"));multi.setChecked(base.optBoolean("multi_select"));box.addView(images);box.addView(multi);LinearLayout options=form(h);box.addView(options);ArrayList<JSONObject> originals=new ArrayList<>();ArrayList<EditText[]> fields=new ArrayList<>();Consumer<JSONObject> add=o->{LinearLayout row=form(h);EditText t=field(h,row,"选项文字",o.optString("text"),false),image=field(h,row,"选项图片地址",o.optString("image"),false);if(upload!=null)row.addView(h.design().button("上传选项图片",false,()->upload.accept(url->{if(alive())image.setText(url);})));EditText[] pair={t,image};originals.add(o);fields.add(pair);row.addView(h.design().button("移除此选项",false,()->{if(fields.size()<=2){h.toast("至少保留两个选项");return;}int index=fields.indexOf(pair);fields.remove(index);originals.remove(index);options.removeView(row);}));options.addView(row);};JSONArray old=base.optJSONArray("options");if(old!=null)for(int i=0;i<old.length();i++)if(old.optJSONObject(i)!=null)add.accept(old.optJSONObject(i));while(fields.size()<2)add.accept(new JSONObject());box.addView(h.design().button("增加选项",false,()->add.accept(new JSONObject())));EditText max=field(h,box,"多选上限（0 不限）",base.optString("max_select","0"),false),start=field(h,box,"开始时间（可空，yyyy-MM-dd HH:mm:ss）",base.isNull("start_at")?"":base.optString("start_at"),false),end=field(h,box,"截止时间（可空）",base.isNull("end_at")?"":base.optString("end_at"),false);box.addView(h.design().text("保存将立即在官网创建或修改投票；正文仍需单独点击插入。",13,h.design().muted,false));AlertDialog form=AuthoringExtras.dialog(h).setTitle(data==null?"创建投票":"修改投票").setView(scroll(h,box)).setNegativeButton("取消",null).setPositiveButton("保存到官网",null).create();submit(form,h,()->{if(!alive())throw new IllegalArgumentException("账号或编辑页面已变化");JSONArray opts=new JSONArray();for(int i=0;i<fields.size();i++){JSONObject o=new JSONObject(originals.get(i).toString());o.put("text",value(fields.get(i)[0])).put("image",value(fields.get(i)[1]));opts.put(o);}JSONObject raw=new JSONObject().put("id",base.optLong("id")).put("title",value(title)).put("options",opts).put("image_mode",images.isChecked()).put("multi_select",multi.isChecked()).put("max_select",Integer.parseInt(value(max))).put("start_at",value(start)).put("end_at",value(end));JSONObject payload=EditorExtraRules.pollPayload(raw);form.getButton(-1).setEnabled(false);form.getButton(-2).setEnabled(false);form.setCancelable(false);h.task(()->{if(h.account()==null||h.account().optLong("id")!=uid)throw new java.io.IOException("账号已切换，请关闭后重试");return h.client().post(data==null?"poll/create":"poll/update",payload);},r->{if(!form.isShowing())return;form.dismiss();if(alive()){h.toast("投票已保存");load();}},e->{if(form.isShowing()){form.getButton(-1).setEnabled(true);form.getButton(-2).setEnabled(true);form.setCancelable(true);h.toast(e);}});});}
    }
}
